/**
 * A weapon's optics: the one it carries by default and those a player may pick for it in their loadout (Profile →
 * Favourite loadout → Optics; docs/GUNPLAY_SPEC.md §15, "Optic choice"). `mag`: its own
 * magnification over the hip view (from its weapon file's `view.zoomFov` or `view.optic`). `mount`: where a
 * housing built in code stands (model space as `view.muzzleAt`: the middle of its foot on the gun's top) and its size:
 * every built housing the gun may carry stands there.
 */
export interface WeaponOptics {
  default: OpticKindId;
  allowed: readonly OpticKindId[];
  mag?: number;
  /** Its own zoom steps, where they differ from its kind's. */
  steps?: readonly number[];
  /** `eye`: on a long gun carrying a red dot or a holographic sight, the eye's model z behind the glass (the glass's line is the view's axis). */
  mount?: { at: readonly [number, number, number]; scale: number; eye?: number };
  /** The model's own open sight instead (no housing is built): its window's middle and half width and height. */
  window?: { at: readonly [number, number, number]; half: readonly [number, number]; round?: boolean };
}

